import { get, handleApiError, post } from '@helpers/httpClient';

import { mapOneFriendToFront } from '../@mappers/user.mappers';
import { IOneFriendDTO, IUserLoginVariant } from '../@types/user.types.dto';

export const getOneFriendData = async (id_user: number) => {
  const res = await get('/ajax/users/get_one_for_frend.php', { id: id_user }).then<IOneFriendDTO>(
    handleApiError,
  );
  const resData = await mapOneFriendToFront(res);
  return resData;
};

export const getFriendsData = async () => {
  const res = await get('/ajax/profile/profile_sym_hiking_users.php').then<IOneFriendDTO[]>(
    handleApiError,
  );
  return res.map(mapOneFriendToFront);
};

export interface IAccountSession {
  id: string;
  date_start: string;
  user_agent: string | null;
  ip: string | null;
  hash: string;
  app_id: string | null;
  app_name: string | null;
  app_img: string | null;
}

export const getAccountSessions = async () => {
  const res = await get('/ajax/profile/sessions.php').then<IAccountSession[]>(handleApiError);
  return res;
};
export const killAccountSessions = async (id: number) => {
  const res = await post('/ajax/profile/sessions_kill.php', { id }).then<{ success: boolean }>(
    handleApiError,
  );
  return res.success;
};

export const getLoginVariants = async () => {
  const res = await get('/ajax/profile/login_variants/login_variants_list.php').then<
    IUserLoginVariant[]
  >(handleApiError);
  return res;
};

export const addLoginVariantLoginPassword = async (data: { login: string; password: string }) => {
  const res = await post('/ajax/profile/login_variants/login_variants_add.php', data).then<{
    success: boolean;
  }>(handleApiError);
  return res.success;
};
export const requestUserEmailConfirm = async (id_login_variant: number) => {
  const res = await post('/ajax/profile/login_variants/confirm_request.php', {
    id_login_variant,
  }).then<{
    success: boolean;
  }>(handleApiError);
  return res.success;
};
export const confirmUserEmailByCode = async (code: string) => {
  const res = await post('/ajax/profile/login_variants/confirm_approve.php', {
    code,
  }).then<{
    success: boolean;
    message?: string;
  }>(handleApiError);
  return res;
};

export const changeUserPassword = ({
  code,
  psw1,
  psw2,
}: {
  code?: string;
  psw1: string;
  psw2: string;
}) => {
  return post('ajax/users/profile/change_password.php', { code, psw1, psw2 }).then<{
    success: boolean;
  }>(handleApiError);
};

export const userPasswordRecovery = (data: {
  loginOrEmail: string;
  redirectTo: string | string[];
}) => {
  return post('ajax/users/profile/recovery_password.php', data).then<{
    success: boolean;
  }>(handleApiError);
};

export interface IUserRegistrationDTO {
  name: string;
  surname: string;
  login: string;
  email: string;
  pass: string;
  dob: string;
  id_app?: string;
}

export const userRegistrationStart = (data: IUserRegistrationDTO) => {
  return post('/ajax/reg_start.php', data).then<{
    success: boolean;
    user?: any;
  }>(handleApiError);
};
